void can_v_id_set_append_lhs (ID_Set * dest , ID_Set * srce)
{
  if (can_v_id_set_peek_lhs (srce))
    {
      #define SRCE ((Q_Node *) srce)
      #define DEST ((Q_Node *) dest)

      SRCE->rhs->lhs = DEST->lhs ;
      SRCE->lhs->rhs = DEST      ;
      DEST->lhs->rhs = SRCE->rhs ;
      DEST->lhs      = SRCE->lhs ;

      #undef  DEST
      #undef  SRCE

      q_init ((Q_Node *) srce) ;
    }

}

//--------------------------------------------------------------------------//

void can_v_id_set_append_rhs (ID_Set * dest , ID_Set * srce)
{
  if (can_v_id_set_peek_rhs (srce))
    {
      #define SRCE ((Q_Node *) srce)
      #define DEST ((Q_Node *) dest)

      SRCE->lhs->rhs = DEST->rhs ;
      SRCE->rhs->lhs = DEST      ;
      DEST->rhs->lhs = SRCE->lhs ;
      DEST->rhs      = SRCE->rhs ;

      #undef  DEST
      #undef  SRCE

      q_init ((Q_Node *) srce) ;
    }
}

